const $=s=>document.querySelector(s),status=$('#review-status'),form=$('#decision-form');
const labels={CREATE:'Start controlled review',SUBMIT:'Submit to responsible unit',UNIT_FORWARD:'Forward to Finance Administrator',FINANCE_FORWARD:'Forward to Principal',APPROVE:'Principal final approval',RETURN:'Return for a new version',REJECT:'Reject',WITHDRAW:'Withdraw'};
let generation=0,current=null,pending=null,busy=false;
const say=text=>status.textContent=text;
const node=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e};
function amendmentType(){const addition=$('#amendment-kind').value==='ADD_ITEM';$('#amendment-extension').hidden=addition;$('#amendment-extension').disabled=addition;$('#amendment-addition').hidden=!addition;$('#amendment-addition').disabled=!addition}
function lock(value){busy=value;for(const el of document.querySelectorAll('button,input,textarea,select'))el.disabled=value;if(!value&&pending)for(const id of ['decision-action','decision-reason','decision-confirm'])$('#'+id).disabled=true;if(!value)amendmentType();if(!value&&pending)for(const el of document.querySelectorAll('#amendment-form input,#amendment-form textarea,#amendment-form select'))el.disabled=true}
async function call(url,body){const response=await fetch(url,{credentials:'same-origin',cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});let data;try{data=await response.json()}catch{throw Error('The review response was unavailable. Refresh to inspect the current state.')}if(!response.ok)throw Error(typeof data.error==='string'?data.error:'Plan review is unavailable.');return data}
function valid(r){return r&&typeof r.planId==='string'&&Number.isSafeInteger(r.planVersion)&&r.planVersion>0&&Number.isSafeInteger(r.workspaceRevision)&&Number.isSafeInteger(r.reviewRevision)&&/^[a-f0-9]{64}$/.test(r.bindingHash)&&r.executionAuthorized===false&&Array.isArray(r.actions)&&r.actions.every(a=>Object.hasOwn(labels,a))&&Array.isArray(r.decisions)&&typeof r.title==='string'&&typeof r.state==='string'&&typeof r.sourceCurrent==='boolean'&&r.sourceDetails&&Array.isArray(r.sourceDetails.items)&&r.sourceDetails.heading&&typeof r.sourceDetails.heading==='object'}
function show(r){
 current=r;$('#review-details').hidden=false;$('#review-title').textContent=r.title;
 const meta=$('#review-meta');meta.replaceChildren();for(const [key,value] of [['Plan',r.planId],['Version',r.planVersion],['Kind',r.kind],['Responsible unit',r.unitId],['Review state',r.state],['Review revision',r.reviewRevision],['Budget',r.budget]])meta.append(node('dt',key),node('dd',String(value)));
 $('#review-warning').textContent=r.baselineCurrent===false?'The approved baseline changed. Rebase this proposal on the latest approved version and obtain fresh reviews.':r.sourceCurrent?'Execution remains unavailable through this review path.':'The source changed after review started. A new version and fresh review are required.';
 const heading=$('#review-source');heading.replaceChildren();for(const [key,value] of Object.entries(r.sourceDetails.heading))heading.append(node('dt',key),node('dd',String(value)));
 const targetRows=r.targetContributions||[];
 const items=$('#review-items');items.replaceChildren();for(const [index,item] of r.sourceDetails.items.entries()){const detail=node('details',''),summary=node('summary',item.title||('Plan item '+(index+1))),fields=node('dl','');for(const [key,value] of Object.entries({...item,...(targetRows.some(p=>p.itemId===item.id)?{targetContributions:targetRows.filter(p=>p.itemId===item.id).map(p=>p.kpiId+' v'+p.kpiVersion+' · '+p.value+' '+p.unit+' ('+p.eventScale+') · target '+p.targetId+' v'+p.targetVersion+' · allocation '+p.allocationId+' v'+p.allocationVersion).join('; ')}:{})}))fields.append(node('dt',key),node('dd',String(value)));detail.append(summary,fields);items.append(detail)}
 $('#review-versions').textContent='Recorded versions: '+(r.versions||[]).map(v=>'v'+v.version+' '+v.state).join(' · ');
 $('#amendment-summary').hidden=!r.amendment;if(r.amendment){$('#amendment-baseline').textContent=(r.amendment.baselineApproved?'Approved baseline':'Previous reviewed version')+' v'+r.amendment.baselineVersion+' · Source v'+r.amendment.previousVersion;$('#amendment-summary-reason').textContent=r.amendment.reason;const table=$('#amendment-changes');table.replaceChildren();for(const c of r.amendment.changes){const row=node('tr','');for(const value of [c.itemId+' · '+(c.field||'new activity'),c.old===null?'New item':String(c.old),typeof c.proposed==='object'?Object.entries(c.proposed).map(([k,v])=>k+': '+v).join('; '):String(c.proposed)])row.append(node('td',value));table.append(row)}}
 const kinds=$('#amendment-kind');kinds.replaceChildren();for(const [value,label] of [['EXTEND_ITEM_DATES','Extend activity dates'],...(!r.amendmentDateOnly?[['ADD_ITEM','Add activity']]:[])]){const option=node('option',label);option.value=value;kinds.append(option)}kinds.value='EXTEND_ITEM_DATES';amendmentType();
 $('#amendment-form').hidden=r.amendmentEligible!==true;$('#amendment-reason').value='';$('#amendment-confirm').checked=false;const choices=$('#amendment-item');choices.replaceChildren();for(const item of r.sourceDetails.items){const option=node('option',item.title||item.id);option.value=item.id;choices.append(option)}
 const history=$('#review-history');history.replaceChildren();for(const d of r.decisions){const row=node('tr','');for(const v of [d.stage,d.action,d.reason,d.at])row.append(node('td',String(v)));history.append(row)}$('#review-empty').hidden=r.decisions.length>0;
 const select=$('#decision-action');select.replaceChildren();for(const a of r.actions){const option=node('option',labels[a]);option.value=a;select.append(option)}form.hidden=!r.actions.length;$('#decision-retry').hidden=true;$('#decision-reason').value='';$('#decision-confirm').checked=false;
}
async function load(){
 if(busy)return;const token=++generation;current=null;pending=null;$('#review-details').hidden=true;lock(true);say('Loading the current plan and reviewer authority…');
 try{const params=new URLSearchParams({planId:$('#plan-id').value.trim(),planVersion:$('#plan-version').value});const data=await call('/api/plan-approvals?'+params);if(token!==generation)return;if(data.available===false){say(data.message||'Institutional plan review is not activated.');return}if(!valid(data.review))throw Error('The plan review could not be validated. Refresh before taking action.');show(data.review);say(data.review.actions.length?'Current version loaded. Choose an authorized action.':data.review.amendmentEligible?'Current version loaded. You may draft a new version.':'Current version loaded. No review action is available to your identity.')}
 catch(error){if(token===generation)say(error.message)}finally{if(token===generation)lock(false)}
}
async function send(){
 if(busy||!pending)return;lock(true);say('Saving the confirmed decision…');
 try{const data=await call('/api/plan-approvals',pending);if(data.available!==true||data.result?.ok!==true||data.result.executionAuthorized!==false)throw Error('The save result could not be verified.');const amendment=pending.action==='DRAFT_AMENDMENT';if(amendment&&Number.isSafeInteger(data.result.planVersion))$('#plan-version').value=String(data.result.planVersion);pending=null;current=null;form.hidden=true;$('#amendment-form').hidden=true;say(amendment?'Amendment draft saved. Load the new version to review and submit it. The baseline is unchanged.':'Decision saved. Load the current review to inspect its history.');$('#decision-retry').hidden=true}
 catch(error){say(error.message+' You may refresh the review or retry the identical request.');$('#decision-retry').hidden=false;$('#decision-save').hidden=true;$('#amendment-save').hidden=true}
 finally{lock(false)}
}
$('#lookup').addEventListener('submit',e=>{e.preventDefault();$('#decision-save').hidden=false;$('#amendment-save').hidden=false;load()});
form.addEventListener('submit',e=>{e.preventDefault();if(!current||pending||!form.reportValidity())return;pending={operationId:crypto.randomUUID(),planId:current.planId,planVersion:current.planVersion,action:$('#decision-action').value,expectedWorkspaceRevision:current.workspaceRevision,expectedReviewRevision:current.reviewRevision,bindingHash:current.bindingHash,reason:$('#decision-reason').value.trim(),confirm:$('#decision-confirm').checked};send()});
$('#decision-retry').addEventListener('click',send);
$('#amendment-kind').addEventListener('change',amendmentType);
$('#amendment-form').addEventListener('submit',e=>{e.preventDefault();if(!current||pending||current.amendmentEligible!==true||!$('#amendment-form').reportValidity())return;
 const addition=$('#amendment-kind').value==='ADD_ITEM';let change;
 if(addition){const value=id=>$('#addition-'+id).value.trim();change={type:'ADD_ITEM',item:{title:value('title'),type:value('type'),start:value('start'),end:value('end'),reportDue:value('report'),participants:Number(value('participants')),venue:value('venue'),budget:value('budget'),lead:value('lead'),mentor:value('mentor'),evidence:value('evidence'),expectedOutput:value('output'),risk:value('risk'),sdg:value('sdg')}}}
 else change={type:'EXTEND_ITEM_DATES',itemId:$('#amendment-item').value,newEnd:$('#amendment-end').value,newReportDue:$('#amendment-report').value};
 pending={operationId:crypto.randomUUID(),planId:current.planId,planVersion:current.planVersion,action:'DRAFT_AMENDMENT',expectedWorkspaceRevision:current.workspaceRevision,expectedReviewRevision:current.reviewRevision,bindingHash:current.bindingHash,changes:[change],reason:$('#amendment-reason').value.trim(),confirm:$('#amendment-confirm').checked};send();
});
const params=new URLSearchParams(location.search);if(params.has('planId'))$('#plan-id').value=params.get('planId');if(params.has('planVersion'))$('#plan-version').value=params.get('planVersion');load();
